var processor = client.CreateProcessor("orders", new ServiceBusProcessorOptions {
    ReceiveMode = ServiceBusReceiveMode.PeekLock, MaxConcurrentCalls = 4 });
processor.ProcessMessageAsync += async args => {
    try {
        await Handle(args.Message);
        await args.CompleteMessageAsync(args.Message);
    } catch (SchemaException ex) {          // permanent: park it, do not retry
        await args.DeadLetterMessageAsync(args.Message, "schema-invalid", ex.Message);
    }                                        // transient: abandon -> delivery count grows
};
